CREATE TABLE fee_structure (fee_structure_id INT UNSIGNED NOT NULL AUTO_INCREMENT,program_id INT UNSIGNED NOT NULL,academic_year_id INT UNSIGNED NOT NULL,fee_name VARCHAR(80) NOT NULL,amount DECIMAL(10,2) NOT NULL,due_date DATE NOT NULL,late_fee_rate DECIMAL(5,2) NOT NULL DEFAULT 2,CONSTRAINT pk_fee_structure PRIMARY KEY(fee_structure_id),CONSTRAINT uq_fee_structure UNIQUE(program_id,academic_year_id,fee_name),CONSTRAINT ck_fee_amount CHECK(amount>0),CONSTRAINT ck_fee_late_rate CHECK(late_fee_rate>=0));
CREATE TABLE fee_structure_audit (fee_audit_id INT UNSIGNED NOT NULL AUTO_INCREMENT,fee_structure_id INT UNSIGNED NOT NULL,old_amount DECIMAL(10,2) NOT NULL,new_amount DECIMAL(10,2) NOT NULL,changed_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT pk_fee_audit PRIMARY KEY(fee_audit_id),CONSTRAINT fk_fee_audit_structure FOREIGN KEY(fee_structure_id) REFERENCES fee_structure(fee_structure_id));
CREATE TABLE fee_payment (fee_payment_id INT UNSIGNED NOT NULL AUTO_INCREMENT,student_id INT UNSIGNED NOT NULL,fee_structure_id INT UNSIGNED NOT NULL,paid_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,base_amount DECIMAL(10,2) NOT NULL,late_fee DECIMAL(10,2) NOT NULL DEFAULT 0,total_amount DECIMAL(10,2) NOT NULL,payment_method ENUM('CASH','CARD','UPI','BANK') NOT NULL,CONSTRAINT pk_fee_payment PRIMARY KEY(fee_payment_id),CONSTRAINT uq_fee_payment_student_structure UNIQUE(student_id,fee_structure_id),CONSTRAINT fk_fee_payment_structure FOREIGN KEY(fee_structure_id) REFERENCES fee_structure(fee_structure_id),CONSTRAINT ck_fee_payment_amount CHECK(base_amount>0 AND late_fee>=0 AND total_amount=base_amount+late_fee));
CREATE TABLE receipt (receipt_id INT UNSIGNED NOT NULL AUTO_INCREMENT,fee_payment_id INT UNSIGNED NOT NULL,receipt_no VARCHAR(30) NOT NULL,issued_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT pk_receipt PRIMARY KEY(receipt_id),CONSTRAINT uq_receipt_payment UNIQUE(fee_payment_id),CONSTRAINT uq_receipt_no UNIQUE(receipt_no),CONSTRAINT fk_receipt_payment FOREIGN KEY(fee_payment_id) REFERENCES fee_payment(fee_payment_id));
CREATE TABLE hostel (hostel_id INT UNSIGNED NOT NULL AUTO_INCREMENT,hostel_name VARCHAR(80) NOT NULL,address VARCHAR(200) NOT NULL,CONSTRAINT pk_hostel PRIMARY KEY(hostel_id),CONSTRAINT uq_hostel_name UNIQUE(hostel_name));
CREATE TABLE hostel_room (hostel_room_id INT UNSIGNED NOT NULL AUTO_INCREMENT,hostel_id INT UNSIGNED NOT NULL,room_no VARCHAR(20) NOT NULL,capacity TINYINT UNSIGNED NOT NULL,CONSTRAINT pk_hostel_room PRIMARY KEY(hostel_room_id),CONSTRAINT uq_hostel_room UNIQUE(hostel_id,room_no),CONSTRAINT fk_hostel_room_hostel FOREIGN KEY(hostel_id) REFERENCES hostel(hostel_id),CONSTRAINT ck_hostel_room_capacity CHECK(capacity>0));
CREATE TABLE hostel_allocation (hostel_allocation_id INT UNSIGNED NOT NULL AUTO_INCREMENT,hostel_room_id INT UNSIGNED NOT NULL,student_id INT UNSIGNED NOT NULL,allocated_on DATE NOT NULL,status ENUM('ACTIVE','ENDED') NOT NULL DEFAULT 'ACTIVE',CONSTRAINT pk_hostel_allocation PRIMARY KEY(hostel_allocation_id),CONSTRAINT uq_hostel_allocation UNIQUE(hostel_room_id,student_id),CONSTRAINT fk_hostel_allocation_room FOREIGN KEY(hostel_room_id) REFERENCES hostel_room(hostel_room_id));
CREATE TABLE notice (notice_id INT UNSIGNED NOT NULL AUTO_INCREMENT,title VARCHAR(150) NOT NULL,body TEXT NOT NULL,audience ENUM('ALL','STUDENT','FACULTY') NOT NULL DEFAULT 'ALL',published_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,expires_at DATETIME NULL,created_by INT UNSIGNED NULL,CONSTRAINT pk_notice PRIMARY KEY(notice_id),CONSTRAINT ck_notice_dates CHECK(expires_at IS NULL OR expires_at>=published_at));
